use vstd::prelude::*;

verus! {
    fn max_of_list(lst: &Vec<usize>) -> (result: usize)
        requires
            lst.len() > 0, // The vector must be non-empty
        ensures
            result == *lst.iter().max().unwrap(), // The result is the maximum element in the vector
            forall |x: usize| lst.contains(&x) ==> x <= result // Every element in the vector is less than or equal to the result
    {
        let mut max_value: usize = lst[0]; // Initialize max_value with the first element of the vector
        let mut idx: usize = 1; // Start from the second element

        while idx < lst.len()
            invariant
                idx <= lst.len(), // idx is within bounds
                max_value == lst[0..idx].iter().cloned().max().unwrap(), // max_value is the maximum of the elements seen so far
                forall |x: usize| lst.contains(&x) ==> x <= max_value, // All elements seen so far are less than or equal to max_value
            decreases lst.len() - idx, // Decreases clause to ensure termination
        {
            if lst[idx] > max_value {
                max_value = lst[idx]; // Update max_value if the current element is greater
            }
            idx += 1; // Move to the next element
        }
        max_value // Return the maximum value found
    }
}

